import{_ as s,a0 as p,w as a,s as r,ao as i,I as l,x as u,a1 as o,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Ubuntu 15.04 终于可以让你将菜单设置为 ‘始终可见’ | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 15.04 终于可以让你将菜单设置为 ‘始终可见’ | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 15.04 终于可以让你将菜单设置为 ‘始终可见’ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 15.04 终于可以让你将菜单设置为 ‘始终可见’ | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150119 Ubuntu 15.04 Finally Lets You Set Menus ToAlways Show","title":"Ubuntu 15.04 终于可以让你将菜单设置为 ‘始终可见’","tag":"201503","desc":""},"relativePath":"201503/20150119 Ubuntu 15.04 Finally Lets You Set Menus ToAlways Show.md","filePath":"[post].md"}'),d={name:"201503/20150119 Ubuntu 15.04 Finally Lets You Set Menus ToAlways Show.md"};function b(m,t,w,f,T,g){const n=p("Link");return a(),r("div",null,[t[18]||(t[18]=i('<h1 id="ubuntu-15-04-终于可以让你将菜单设置为-始终可见" tabindex="-1">Ubuntu 15.04 终于可以让你将菜单设置为 ‘始终可见’ <a class="header-anchor" href="#ubuntu-15-04-终于可以让你将菜单设置为-始终可见" aria-label="Permalink to “Ubuntu 15.04 终于可以让你将菜单设置为 ‘始终可见’”">​</a></h1><p><strong>如果你不喜欢 Unity 的全局菜单在你的鼠标离开后就淡出你的视野，在 Ubuntu 15.04 稍微做点工作就可以留住菜单。</strong></p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/02/locally-integrated-menus-in-ubuntu.png" alt=""></p><p>最新的Ubuntu 15.04的Unity界面通过在“提议（Proposed）”通道提供了一个选项，<strong>使应用程序菜单在Ubuntu中始终可见</strong>。</p><p>这是个不会淡出，也不会过段时间就消失的菜单。</p><p>最大的缺点是它目前只能通过<code>dconf</code>来控制，而不是常规的面向用户的选项设置。</p><p>我希望（如果预计没有的话）在之后的开发中，能有一个设置这个特性的选项被加入到Ubuntu的【系统设置】&gt;【外观】部分。</p><p>现在，如果你使用的是 Ubuntu 15.04，并启用了“提议（Proposed）”的更新通道后，你可以在dconf 的com&gt;canonical&gt;Unity&gt;‘always show menus’ 中找到这个开关。</p><h3 id="迟到总比没有要好" tabindex="-1">迟到总比没有要好? <a class="header-anchor" href="#迟到总比没有要好" aria-label="Permalink to “迟到总比没有要好?”">​</a></h3><p>开发者们计划在Ubuntu 14.04 LTS的下一个SRU中反向移植这个选项（假设在测试阶段没有任何意外发生）。</p><p>本地集成菜单（LIM）在Ubuntu 14.04 LTS 中的首次亮相就赢得了赞誉，其被广泛认为在那些喜欢隐藏方式的与那些不喜欢必须使用鼠标和触摸板的人之间的最佳的折衷方案。</p><p>虽然在Unity方面本地集成菜单减少了不少批评，不过默认的“淡入/淡出”行为总是还让人不爽。</p>',12)),l("p",null,[t[2]||(t[2]=u("在Ubuntu 过去的几个版本中已经能够看到他们在积极解决早期的用户体验中的几个痛点。经过了几年，在TODO列表中",-1)),o(n,{href:"http://www.omgubuntu.co.uk/2014/02/locally-integrated-menus-ubuntu-14-04"},{default:e(()=>[...t[0]||(t[0]=[u("我们去年终于看到了本地集成菜单",-1)])]),_:1}),t[3]||(t[3]=u("，以及通过",-1)),o(n,{href:"http://www.omgubuntu.co.uk/2014/03/minimize-click-launcher-option-ubuntu-14-04"},{default:e(()=>[...t[1]||(t[1]=[u("点击应用图标来实现Unity 启动器中应用的最小化及恢复的选项",-1)])]),_:1}),t[4]||(t[4]=u("。",-1))]),t[19]||(t[19]=l("p",null,"一年以来我们终于看到了一个使应用程序菜单始终显示的选项，无论我们的鼠标在哪里。迟来总比没有好，对不对？",-1)),t[20]||(t[20]=l("hr",null,null,-1)),l("p",null,[t[6]||(t[6]=u("via: ",-1)),o(n,{href:"http://www.omgubuntu.co.uk/2015/01/ubuntu-15-04-always-show-menu-bar-option"},{default:e(()=>[...t[5]||(t[5]=[u("http://www.omgubuntu.co.uk/2015/01/ubuntu-15-04-always-show-menu-bar-option",-1)])]),_:1})]),l("p",null,[t[10]||(t[10]=u("作者：",-1)),o(n,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:e(()=>[...t[7]||(t[7]=[u("Joey-Elijah Sneddon",-1)])]),_:1}),t[11]||(t[11]=u(" 译者：",-1)),o(n,{href:"https://github.com/JeffDing"},{default:e(()=>[...t[8]||(t[8]=[u("JeffDing",-1)])]),_:1}),t[12]||(t[12]=u(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[9]||(t[9]=[u("wxy",-1)])]),_:1})]),l("p",null,[t[15]||(t[15]=u("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[13]||(t[13]=[u("LCTT",-1)])]),_:1}),t[16]||(t[16]=u(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:e(()=>[...t[14]||(t[14]=[u("Linux中国",-1)])]),_:1}),t[17]||(t[17]=u(" 荣誉推出",-1))])])}const S=s(d,[["render",b]]);export{L as __pageData,S as default};
